use serde_json::{Value,json};use std::sync::Mutex;use tauri::{Manager,State};use storage::Database;
struct Runtime {monitor:Mutex<system_info::Monitor>,operation:Mutex<()>}
#[tauri::command]fn preview_game_settings(options:game_optimizer::Options)->Result<Value,String>{game_optimizer::preview(options)}
#[tauri::command]fn apply_game_settings(db:State<Database>,runtime:State<Runtime>,expected:String,options:game_optimizer::Options,confirmed:bool)->Result<Value,String>{if !confirmed{return Err("Confirme as alterações gráficas".into())}let _guard=runtime.operation.lock().map_err(|e|e.to_string())?;game_optimizer::apply(&db,expected,options)}
#[tauri::command]fn startup_entries()->Result<Value,String>{startup_manager::inventory()}
#[tauri::command]fn disable_startup(db:State<Database>,runtime:State<Runtime>,name:String,expected:String,confirmed:bool)->Result<Value,String>{if !confirmed{return Err("Confirme a desativação da entrada de arranque".into())}let _guard=runtime.operation.lock().map_err(|e|e.to_string())?;startup_manager::disable(&db,&name,&expected)}
#[tauri::command]fn ui_preferences()->Result<Value,String>{Ok(json!([{"ClientAnimation":optimization_engine::read("visual.client_animation")?,"MenuAnimation":optimization_engine::read("visual.menu_animation")?,"TooltipAnimation":optimization_engine::read("visual.tooltip_animation")?}]))}
#[tauri::command]async fn snapshot(app:tauri::AppHandle)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||{let runtime=app.state::<Runtime>();let value=runtime.monitor.lock().map_err(|e|e.to_string())?.snapshot();Ok(value)}).await.map_err(|e|e.to_string())?}
#[tauri::command]async fn processes(app:tauri::AppHandle)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||{let runtime=app.state::<Runtime>();let value=runtime.monitor.lock().map_err(|e|e.to_string())?.processes();Ok(value)}).await.map_err(|e|e.to_string())?}
#[tauri::command]async fn latency_test(address:String)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||network_monitor::latency(&address)).await.map_err(|e|e.to_string())?}
#[tauri::command]async fn inventory(db:State<'_,Database>,kind:String)->Result<Value,String>{let label=kind.clone();let result=tauri::async_runtime::spawn_blocking(move||windows_inventory::query(&kind)).await.map_err(|e|e.to_string())?;if let Err(error)=&result{let _=db.log("inventory.error",&json!({"source":label,"error":error}).to_string());}result}
