#[tauri::command]fn terminate_process(db:State<Database>,pid:u32,start:u64,confirmed:bool)->Result<(),String>{if !confirmed{return Err("É necessária confirmação".into())}let result=process_manager::terminate(pid,start);db.log("process.terminate",&json!({"pid":pid,"start":start,"result":result}).to_string())?;result}
#[tauri::command]async fn cleaner_scan()->Result<Value,String>{tauri::async_runtime::spawn_blocking(||disk_cleaner::scan().map(|x|json!(x))).await.map_err(|e|e.to_string())?}
#[tauri::command]fn cleaner_delete(db:State<Database>,files:Vec<disk_cleaner::Candidate>,confirmed:bool)->Result<Value,String>{if !confirmed{return Err("Confirme a eliminação permanente".into())}db.log("cleaner.intent",&json!(files).to_string())?;let result=disk_cleaner::delete(files)?;db.log("cleaner.result",&result.to_string())?;Ok(result)}
#[tauri::command]fn save_benchmark(db:State<Database>,runtime:State<Runtime>,label:String,conditions:String)->Result<(),String>{if label.trim().is_empty()||label.len()>200||conditions.trim().is_empty()||conditions.len()>4000{return Err("Indique um nome e as condições do teste".into())}let snap=runtime.monitor.lock().map_err(|e|e.to_string())?.snapshot();db.0.lock().map_err(|e|e.to_string())?.execute("INSERT INTO benchmarks(label,conditions,snapshot) VALUES(?1,?2,?3)",rusqlite::params![label,conditions,snap.to_string()]).map_err(|e|e.to_string())?;db.log("benchmark.save","Amostra instantânea; não é um teste de FPS")}
#[tauri::command]fn save_snapshot(db:State<Database>,kind:String,data:Value)->Result<(),String>{if !["services","hardware","startup","tasks"].contains(&kind.as_str())||data.to_string().len()>8_000_000{return Err("Snapshot inválido".into())}db.0.lock().map_err(|e|e.to_string())?.execute("INSERT INTO snapshots(kind,data) VALUES(?1,?2)",rusqlite::params![kind,data.to_string()]).map_err(|e|e.to_string())?;Ok(())}
#[tauri::command]fn save_profile(db:State<Database>,name:String,executable:String,profile:String)->Result<(),String>{if name.trim().is_empty()||name.len()>200||!["Balanced","Gaming","Custom"].contains(&profile.as_str()){return Err("Perfil inválido".into())}let path=game_manager::validate(&executable)?;db.0.lock().map_err(|e|e.to_string())?.execute("INSERT INTO profiles(name,executable,profile) VALUES(?1,?2,?3)",rusqlite::params![name,path.to_string_lossy(),profile]).map_err(|e|e.to_string())?;Ok(())}
#[tauri::command]fn launch_game(db:State<Database>,id:i64,confirmed:bool)->Result<(),String>{if !confirmed{return Err("Confirme o lançamento".into())}let path:String=db.0.lock().map_err(|e|e.to_string())?.query_row("SELECT executable FROM profiles WHERE id=?1",[id],|r|r.get(0)).map_err(|e|e.to_string())?;let path=game_manager::validate(&path)?;std::process::Command::new(&path).current_dir(path.parent().ok_or("Pasta inválida")?).spawn().map_err(|e|e.to_string())?;db.log("game.launch",&path.to_string_lossy())}
#[tauri::command]fn open_restore_tools()->Result<(),String>{let tool=std::path::PathBuf::from(std::env::var_os("SystemRoot").ok_or("SystemRoot ausente")?).join("System32/SystemPropertiesProtection.exe");let wide:Vec<u16>=tool.to_string_lossy().encode_utf16().chain(Some(0)).collect();let result=unsafe{windows_sys::Win32::UI::Shell::ShellExecuteW(std::ptr::null_mut(),std::ptr::null(),wide.as_ptr(),std::ptr::null(),std::ptr::null(),1)};if result as isize<=32{return Err("Não foi possível abrir a Proteção do Sistema; o Windows pode exigir autorização administrativa para esta ferramenta".into())}Ok(())}
#[tauri::command]fn open_settings(page:String)->Result<(),String>{let uri=match page.as_str(){"apps"=>"ms-settings:appsfeatures","startup"=>"ms-settings:startupapps","gaming"=>"ms-settings:gaming-gamemode","capture"=>"ms-settings:gaming-gamedvr","power"=>"ms-settings:powersleep","graphics"=>"ms-settings:display-advancedgraphics","network"=>"ms-settings:network-status","privacy"=>"ms-settings:privacy","update"=>"ms-settings:windowsupdate",_=>return Err("Página não permitida".into())};let wide:Vec<u16>=uri.encode_utf16().chain(Some(0)).collect();let result=unsafe{windows_sys::Win32::UI::Shell::ShellExecuteW(std::ptr::null_mut(),std::ptr::null(),wide.as_ptr(),std::ptr::null(),std::ptr::null(),1)};if result as isize<=32{return Err("Não foi possível abrir as Definições".into())}Ok(())}
#[tauri::command]fn save_setting(db:State<Database>,key:String,value:String)->Result<(),String>{if !["profile","refresh","reduced_motion","notifications"].contains(&key.as_str())||value.len()>100{return Err("Definição inválida".into())}db.0.lock().map_err(|e|e.to_string())?.execute("INSERT INTO settings(key,value) VALUES(?1,?2) ON CONFLICT(key) DO UPDATE SET value=excluded.value",rusqlite::params![key,value]).map_err(|e|e.to_string())?;Ok(())}
#[tauri::command]fn load_settings(db:State<Database>)->Result<Value,String>{let c=db.0.lock().map_err(|e|e.to_string())?;let mut s=c.prepare("SELECT key,value FROM settings").map_err(|e|e.to_string())?;let rows=s.query_map([],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?))).map_err(|e|e.to_string())?;let mut o=serde_json::Map::new();for row in rows{let(k,v)=row.map_err(|e|e.to_string())?;o.insert(k,json!(v));}Ok(Value::Object(o))}
fn main(){let args:Vec<_>=std::env::args_os().collect();if args.get(1).is_some_and(|v|v=="--service-fixture-never-run"){std::process::exit(0)}if args.get(1).is_some_and(|v|v=="--isolated-fixture-test"){if args.len()!=3{std::process::exit(2)}let result=isolated_tests::run(std::path::Path::new(&args[2]));if let Err(error)=&result{eprintln!("{error}");}std::process::exit(if result.is_ok(){0}else{1});}if args.get(1).is_some_and(|v|v=="--service-helper"){if args.len()!=6{std::process::exit(2)}let parsed=(||{let name=args[2].to_str().ok_or("name")?;let expected=args[3].to_str().ok_or("expected")?.parse::<u32>().map_err(|_|"expected")?;let target=args[4].to_str().ok_or("target")?.parse::<u32>().map_err(|_|"target")?;let delayed=match args[5].to_str(){Some("0")=>false,Some("1")=>true,_=>return Err("delay")};service_changes::helper(name,expected,target,delayed).map_err(|_|"refused")})();std::process::exit(if parsed.is_ok(){0}else{1});}if args.get(1).is_some_and(|v|v=="--self-test"){if args.len()!=3{std::process::exit(2);}match self_test::run(std::path::Path::new(&args[2])){Ok(())=>std::process::exit(0),Err(error)=>{eprintln!("{error}");std::process::exit(1)}}}tauri::Builder::default().setup(|app|{let path=app.path().app_local_data_dir()?;std::fs::create_dir_all(&path)?;let db=Database::open(&path.join("lucioz.db")).map_err(std::io::Error::other)?;db.log("app.start","Least privilege; version 0.3.0").map_err(std::io::Error::other)?;app.manage(db);app.manage(game_sessions::GameControl::default());app.manage(benchmark_engine::BenchmarkControl::default());app.manage(Runtime{monitor:Mutex::new(system_info::Monitor::new()),operation:Mutex::new(())});Ok(())}).invoke_handler(tauri::generate_handler![desktop_commands::power_plans,desktop_commands::apply_power_plan,desktop_commands::preview_profile,desktop_commands::apply_profile_action,desktop_commands::review_service,desktop_commands::set_service_manual,desktop_commands::disable_task,desktop_commands::preview_game_session,desktop_commands::launch_game_session,desktop_commands::recycle_info,desktop_commands::empty_recycle,desktop_commands::large_files,desktop_commands::open_documentation,open_restore_tools,preview_game_settings,apply_game_settings,startup_entries,disable_startup,session_commands::record_benchmark,session_commands::cancel_benchmark,session_commands::save_fps_session,session_commands::get_session,latency_test,ui_preferences,snapshot,processes,inventory,service_details,history,preview_changes,apply_change,desktop_commands::restore_change,terminate_process,cleaner_scan,cleaner_delete,save_benchmark,save_snapshot,save_profile,launch_game,open_settings,save_setting,load_settings]).run(tauri::generate_context!()).expect("Não foi possível iniciar a aplicação");}
